class Solution {
public:
    int totalNumbers(vector<int>& digits) {
        int freq[10] = {0};
        for (int d : digits) freq[d]++;
        int count = 0;
        int evens[5] = {0, 2, 4, 6, 8};
        for (int a = 1; a <= 9; a++) {
            if (freq[a] < 1) continue;
            freq[a]--;
            for (int b = 0; b <= 9; b++) {
                if (freq[b] < 1) continue;
                freq[b]--;
                for (int k = 0; k < 5; k++) {
                    if (freq[evens[k]] >= 1) count++;
                }
                freq[b]++;
            }
            freq[a]++;
        }
        return count;
    }
};
